import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const envPath = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '.env');

export function parseEnv(text) {
  const env = {};
  for (let line of text.replace(/^﻿/, '').split(/\r?\n/)) {
    line = line.trim();
    if (!line || line.startsWith('#')) continue;
    line = line.replace(/^export\s+/, '');
    const i = line.indexOf('=');
    if (i < 0) continue;
    const key = line.slice(0, i).trim();
    let value = line.slice(i + 1).trim();
    if (/^(['"]).*\1$/.test(value)) value = value.slice(1, -1);
    env[key] = value;
  }
  return env;
}

let text = '';
try {
  text = fs.readFileSync(envPath, 'utf8');
} catch {
  console.error(`Error: could not read ${envPath}`);
  process.exit(1);
}
const env = { ...parseEnv(text), ...(process.env.GEMINI_API_KEY ? { GEMINI_API_KEY: process.env.GEMINI_API_KEY } : {}) };
if (!env.GEMINI_API_KEY) { console.error('Error: GEMINI_API_KEY is missing'); process.exit(1); }

